INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(41845, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah… The weight that leaves my very being dissipates as we speak. Being whole once more, passing into the afterlife may not be just a desperate plea anymore. $C, my sincerest thank you. Had it been not for you, I and many others would have been anchored in the world of the living still. My heart rests more easily now, thanks to you. Please, accept one of my remaining physical possessions as a just reward for you.', 0),
(41879, 0, 0, 0, 0, 0, 0, 0, 0, 'The crystal!$B$B<Grukson turns it over in his hands, clearly impressed.>$B$BIt\'s just how I imagined it—absolutely perfect. This will make the mace something truly special.$B$BI\'d better get to work, then. Maybe this time… my father will finally see what I\'m capable of.', 0),
(41840, 0, 0, 0, 0, 0, 0, 0, 0, 'What…? What is this? Where did you…?! No, no, no! Timothy! My little Timmy, no! Oh, Light, why have you forsaken me?! He was just a boy, my sweet, innocent boy!$B$B<Judith is breaking down. Hysteric crying and yelling is all she can do right now. You did what you could. Atleast she has certainty now.>', 0),
(41841, 0, 0, 0, 0, 0, 0, 0, 0, 'Look what the cat dragged in. I was assuming Wordeen had atleast a smidgeon of competency left in his body, but I was sorely mistaken, it seems. To think one of my artifacts escaped those irritating mages and ended up in the clutches of the Shadow Council. Curious, indeed…$B$B$N, with the return of the pendant, I am closing the book on this unfortunate circumstance among my subordinates. The traitors have been dealt with, my relics are secured and you… You shall be rewarded for delivering a decisive strike against those misusing my possessions.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(41845, 0, 0, 'She is a sadistic creature, torturing souls for her own enjoyment. Her retribution cannot come sooner.', 0),
(41879, 0, 0, 'Have you found the crystal yet?', 0),
(41840, 0, 0, '<Judith is still sobbing.>$B$BOh, Sara, my darling angel… By the Light, please let my Timothy be safe…!', 0),
(41841, 0, 0, 'Speak quickly. I don’t intend to waste my time with vermin.', 0);
