INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(62547, 0, 0, 'More meat to devour!', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Dagar the Glutton - Aggro'),
(62547, 1, 0, 'The hunger... never ends...', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Dagar the Glutton - Death'),
(62548, 0, 0, 'Let me tear your heart asunder!', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Oronok Torn-Heart - Aggro'),
(62548, 1, 0, 'Gul\'dan...! Your legacy...', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Oronok Torn-Heart - Death'),
(62549, 0, 0, 'Yet again do the forces of darkness seek to lay claim to my throne. Stormwrought will not fall into your hands, fiends!', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Duke Balor IV - Aggro'),
(62549, 1, 0, 'Olivert... Philmore... Old friends...', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Duke Balor IV - Death'),
(62550, 0, 0, 'Step forth. Accept the cold embrace of death and drown in its bleakness!', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Deathlord Tidebane - Aggro'),
(62550, 1, 0, 'The waves... they beckon me...', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Deathlord Tidebane - Death'),
(62550, 2, 0, 'Darkness shall come, and consume you all!', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Deathlord Tidebane - Wail of Souls'),
(62551, 0, 0, 'The dark sea will swallow your souls!', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Chieftain Stormsong - Aggro'),
(62551, 1, 0, 'You know so little, whelps...', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Chieftain Stormsong - Death'),
(62552, 0, 0, 'I must kindly ask you to leave, the archives are not ready for public viewing!', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Librarian Theodorus - Aggro'),
(62552, 1, 0, 'These pages were mine to organize... Such great effort, gone to waste!', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Librarian Theodorus - Death'),
(62552, 2, 0, 'Behold, my signature attack! The great waves of Balor shall destroy you, once and for all!', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Librarian Theodorus - Summon Enraged Sea Elemental'),
(62652, 0, 0, 'You shall be brought under heel intruder...', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Subjugator Halthas Shadecrest - Aggro'),
(62652, 1, 0, 'This cannot be! I was going to change the world!', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Subjugator Halthas Shadecrest - Death'),
(62652, 2, 0, 'My will is unbreakable, you shall bend your knee.', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Subjugator Halthas Shadecrest - Dominate Mind'),
(62665, 0, 0, 'New toys, let\'s hope you will not break so easily...', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Lady Drazare - Aggro'),
(62665, 1, 0, 'Impossible... You... vile...', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Lady Drazare - Death'),
(62665, 2, 0, 'Share your darkest secrets with me!', 12, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Lady Drazare - Dark Seduction'),
(62671, 0, 0, 'My master prepared me for this moment. Those ignorant to his truth will perish by my hands.', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Ighalfor - Temple of Shadows'),
(62671, 1, 0, 'Your intrusion ends here!', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Ighalfor - Aggro'),
(62671, 2, 0, 'Enough! The Bloodstone is ready; savor the last fleeting moments of your life!', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Ighalfor - Channeling'),
(62671, 3, 0, 'Great Mergothid, lay your eyes upon this feast of souls!', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Ighalfor - Mergothid Spawn'),
(62673, 0, 0, 'Too soon, incessant weakling. Your pathetic soul will be the compensation for your failure.', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Mergothid - Release'),
(62673, 1, 0, 'More souls to feast upon!', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Mergothid - 50% Health'),
(62673, 2, 0, 'The nether, calls yet again!', 14, 0, 100, 0, 0, 0, 0, 0, 'Stormwrought Ruins - Mergothid - Death');
